<!DOCTYPE html><html lang="id"><head><meta charset="utf-8"><title>Tagihan {{ $settings['name'] }}</title><style>@page{margin:30px}body{font-family:DejaVu Sans,Arial,sans-serif;font-size:11px;color:#253c31}.invoice{page-break-after:always}.invoice:last-child{page-break-after:auto}.header{border-bottom:2px solid #226b52;padding-bottom:15px;margin-bottom:20px}h1{font-size:22px;margin:0 0 5px}h2{font-size:16px}p{line-height:1.7}.muted{color:#6c7c72}table{width:100%;border-collapse:collapse;margin:15px 0}th,td{padding:9px;text-align:left;border-bottom:1px solid #e0e8de}th{background:#eff5eb}thead{display:table-header-group}.right{text-align:right}.total{font-size:16px;font-weight:bold;background:#f1f6ec}.info{width:100%}.info td{border:0;padding:3px}.note{padding:13px;background:#f7f9f4;border:1px solid #dfe8d8}.toolbar{margin-bottom:20px}.cancelled{color:#aa4444;font-size:18px;font-weight:bold}@media print{.toolbar{display:none}}</style></head><body><div class="toolbar"><button onclick="window.print()">Cetak tagihan</button></div>@forelse($invoices as $invoice)<section class="invoice"><div class="header"><h1>{{ $settings['name'] }}</h1><span>{{ $settings['address'] }}</span><br><span class="muted">{{ $settings['contact'] }}</span></div><h2>TAGIHAN REKENING AIR</h2>@if($invoice->status==='cancelled')<p class="cancelled">DIBATALKAN · {{ $invoice->cancellation_reason }}</p>@endif<table class="info"><tr><td>Nomor tagihan</td><td><strong>{{ $invoice->number }}</strong></td><td>Periode</td><td>{{ $invoice->period->name }}</td></tr><tr><td>ID pelanggan</td><td>{{ $invoice->customer_snapshot['number'] }}</td><td>Jatuh tempo</td><td>{{ $invoice->due_date->format('d/m/Y') }}</td></tr><tr><td>Nama</td><td>{{ $invoice->customer_snapshot['name'] }}</td><td>Wilayah</td><td>{{ $invoice->customer_snapshot['rt_name'] }} / RW.{{ $invoice->customer_snapshot['rw'] }}</td></tr><tr><td>Alamat</td><td colspan="3">{{ $invoice->customer_snapshot['address'] }}</td></tr><tr><td>Kategori</td><td>{{ $invoice->customer_snapshot['category_name'] }}</td><td>Tarif</td><td>{{ $invoice->tariff_snapshot['name'] }} v{{ $invoice->tariff_snapshot['version'] }}</td></tr></table><table><thead><tr><th>Nomor meter</th><th>Angka sebelumnya</th><th>Angka saat ini</th><th>Pemakaian</th></tr></thead><tbody>@foreach($invoice->customer_snapshot['meter_segments']??[] as $segment)<tr><td>{{ $segment['serial'] }}</td><td>{{ $segment['previous'] }} m³</td><td>{{ $segment['current'] }} m³</td><td>{{ $segment['usage'] }} m³</td></tr>@endforeach<tr><td colspan="3">Total pemakaian</td><td>{{ $invoice->usage }} m³</td></tr></tbody></table><table><thead><tr><th>Rincian biaya</th><th>Jumlah</th><th>Tarif satuan</th><th class="right">Nominal</th></tr></thead><tbody>@foreach($invoice->lines as $line)<tr><td>{{ $line['description'] }}</td><td>{{ $line['quantity']??'—' }}</td><td>@rupiah($line['rate']??0)</td><td class="right">@rupiah($line['amount'])</td></tr>@endforeach<tr class="total"><td colspan="3">Total tagihan periode ini</td><td class="right">@rupiah($invoice->total)</td></tr><tr><td colspan="3">Pembayaran dialokasikan</td><td class="right">@rupiah($invoice->paid_amount)</td></tr><tr><td colspan="3"><strong>Sisa tagihan periode ini</strong></td><td class="right"><strong>@rupiah($invoice->status==='cancelled'?0:$invoice->total-$invoice->paid_amount)</strong></td></tr></tbody></table>@php($arrears=\App\Models\Invoice::where('customer_id',$invoice->customer_id)->whereIn('status',['issued','partial'])->whereHas('period',fn($q)=>$q->where('starts_on','<',$invoice->period->starts_on))->get())@if($arrears->isNotEmpty())<h3>Tunggakan periode sebelumnya (terpisah)</h3><table><thead><tr><th>Nomor tagihan</th><th>Periode</th><th class="right">Sisa</th></tr></thead><tbody>@foreach($arrears as $old)<tr><td>{{ $old->number }}</td><td>{{ $old->period->name }}</td><td class="right">@rupiah($old->total-$old->paid_amount)</td></tr>@endforeach</tbody></table>@endif<p class="note">{{ $settings['bank'] }}<br>{{ $settings['note'] }}</p><p class="muted">Status: {{ \App\Support\Format::status($invoice->status) }} · Dicetak {{ now()->format('d/m/Y H:i') }} WIB<br>Dokumen tagihan ini bukan bukti pembayaran.</p></section>@empty<p>Tidak ada tagihan sesuai filter.</p>@endforelse</body></html>
